{
  "results": [
    {
      "criterion_id": "criterion-1",
      "passed": true,
      "evidence": [
        "final_message 第1节分别列出已确认事实、当前假设和待确认信息，并明确接口字段、角色权限矩阵、支付最终状态规则尚未提供。",
        "final_message 第1节说明“成功、失败、处理中”只是业务含义，不是接口状态枚举。"
      ],
      "failures": []
    },
    {
      "criterion_id": "criterion-2",
      "passed": true,
      "evidence": [
        "final_message 的 C01 覆盖登录、加购、下单、支付成功和订单刷新；C02 覆盖同一有效回调的串行重放及并发到达。",
        "final_message 的 C03–C06 覆盖越权、非法数量与库存、延迟回调、无效验签及金额或归属不匹配；C11–C12 补充支付失败重试和乱序回调。"
      ],
      "failures": []
    },
    {
      "criterion_id": "criterion-3",
      "passed": true,
      "evidence": [
        "final_message 第2节按 P0/P1 排序，第5节将 30 分钟分配给准备、C01–C06 和结果汇总。",
        "final_message 明确 C07–C13 不计入首轮窗口，并列出持续高并发、多渠道、退款对账等未验证风险。"
      ],
      "failures": []
    },
    {
      "criterion_id": "criterion-4",
      "passed": true,
      "evidence": [
        "final_message 第4节的 C01–C06 表格逐项列有前置条件、操作、预期判断和必留证据。",
        "例如 C02 要求独立订单及可重放回调，执行串行三次和并发两次发送，并核对前后记账、库存、履约记录，不能只凭接口返回成功判通过。"
      ],
      "failures": []
    },
    {
      "criterion_id": "criterion-5",
      "passed": true,
      "evidence": [
        "final_message 明确本次仅设计方案、全部用例均未执行，且 P0 阻塞、待确认或未执行时不能给出验证通过结论。",
        "final_message 第5节列出生产环境、真实资金影响、重复资金处理等停止或升级条件；第6节列出待补信息及下一步执行顺序。"
      ],
      "failures": []
    }
  ]
}
